import { Component, OnInit } from '@angular/core';
import { FormGroup, FormBuilder, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { ToastController, LoadingController, AlertController } from '@ionic/angular';
import { GResponse } from 'src/app/core/common/GResponse';
import { ProductDesignViewModel } from 'src/app/data/model/product/AddOrUpdateProductModel';
import { IProductDetailModel, ProductDetailModel } from 'src/app/data/model/product/ProductDetailModel';
import { IProductFilterModel, ProductFilterModel } from 'src/app/data/model/product/ProductFilterModel';
import { IProductModel } from 'src/app/data/model/product/ProductModel';
import { ProductService } from 'src/app/data/service/product/product.service';
import { SharedIonic } from '../../../../../core/common/SharedIonic';
import { Title } from '@angular/platform-browser';

@Component({
  selector: 'app-product-designs',
  templateUrl: './product-designs.component.html',
  styleUrls: ['./product-designs.component.scss']
})
export class ProductDesignsComponent implements OnInit {

  segmentSelected = 'Add';
  searchTitle = '';
  selectedProductId = 0;
  productSelected = false;
  productDetail: IProductDetailModel;
  productDetail2: IProductDetailModel;
  product: IProductModel;
  filteredProducts: IProductFilterModel;
  updateForm: FormGroup;
  updateForm2: FormGroup;
  addForm: FormGroup;
  selectedVideoIndex = -1;
  empty = false;

  constructor(
    private productService: ProductService,
    private fb: FormBuilder,
    public toastController: ToastController,
    public loadingController: LoadingController,
    private activatedRoute: ActivatedRoute,
    public alertController: AlertController,
    private router: Router) { }

  ngOnInit(): void {

    this.updateForm = this.fb.group({
      title: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(10000)]],
      description: ['', [Validators.minLength(0), Validators.maxLength(1000000)]],
      price: [0, [Validators.required, Validators.min(1000), Validators.max(90000000000)]],
      offPrice: [0, [Validators.required, Validators.min(0), Validators.max(90000000000)]],
      count: [0, [Validators.required, Validators.min(0), Validators.max(20000000)]],
      weight: [0, [Validators.required, Validators.min(1), Validators.max(20000000)]],
      isShow: [true, [Validators.required]]
    });

    this.updateForm2 = this.fb.group({
      title: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(10000)]],
      description: ['', [Validators.minLength(0), Validators.maxLength(1000000)]],
      price: [0, [Validators.required, Validators.min(1000), Validators.max(90000000000)]],
      offPrice: [0, [Validators.required, Validators.min(0), Validators.max(90000000000)]],
      count: [0, [Validators.required, Validators.min(0), Validators.max(20000000)]],
      weight: [0, [Validators.required, Validators.min(1), Validators.max(20000000)]],
      isShow: [true, [Validators.required]]
    });

    this.addForm = this.fb.group({
      title: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(10000)]],
      description: ['', [Validators.minLength(0), Validators.maxLength(1000000)]],
      price: [0, [Validators.required, Validators.min(1000), Validators.max(90000000000)]],
      offPrice: [0, [Validators.required, Validators.min(0), Validators.max(90000000000)]],
      count: [0, [Validators.required, Validators.min(0), Validators.max(20000000)]],
      weight: [0, [Validators.required, Validators.min(1), Validators.max(20000000)]],
      isShow: [true, [Validators.required]]
    });

    let filter: IProductFilterModel;

    this.activatedRoute.queryParams.subscribe(params => {

      const page = params.page;
      const take = params.take ? params.take : 12;
      const title = params.title ? params.title : null;
      const startPrice = params.startPrice ? params.startPrice : null;
      const endPrice = params.endPrice ? params.endPrice : null;
      const categoryIds = params.categoryIds ? params.categoryIds : [];
      const sortId = params.sortId ? params.sortId : 4;

      if (page === undefined) {
        filter =
          new ProductFilterModel(false, page, take, title);
      } else {
        if (
          startPrice == null &&
          endPrice == null &&
          categoryIds == null &&
          sortId == null) {

          filter = new ProductFilterModel(false, page, take, title);
        } else {
          filter =
            new ProductFilterModel(true, page, take, title, startPrice, endPrice, categoryIds, sortId);
        }
      }
      this.filteredProducts = filter;

      SharedIonic.loading(this.loadingController);

      this.productService.GetAdminProductsByFilter(filter).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (res.status === GResponse.SuccessStatus) {
            this.filteredProducts = res.data;
          } else {
            this.empty = true;
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    });
  }

  onSelectVideo(index: number | string): void {

    this.selectedVideoIndex = +index;

    this.updateForm.setValue({
      title: this.productDetail.productDesigns[+index].title,
      description: this.productDetail.productDesigns[+index].description,
      isShow: this.productDetail.productDesigns[+index].isShow,
      price: this.productDetail.productDesigns[+index].price,
      offPrice: this.productDetail.productDesigns[+index].offPrice,
      weight: this.productDetail.productDesigns[+index].weight,
      count: this.productDetail.productDesigns[+index].count
    });

    this.updateForm2.setValue({
      title: this.productDetail2.productDesigns[+index].title,
      description: this.productDetail2.productDesigns[+index].description,
      isShow: this.productDetail2.productDesigns[+index].isShow,
      price: this.productDetail2.productDesigns[+index].price,
      offPrice: this.productDetail2.productDesigns[+index].offPrice,
      weight: this.productDetail2.productDesigns[+index].weight,
      count: this.productDetail2.productDesigns[+index].count
    });
  }

  async presentAlertConfirm(index) {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به حذف هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'حذف',
          handler: () => {
            this.onDelete(index);
          }
        }
      ]
    });

    await alert.present();
  }

  async presentAlertConfirm2() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onUpdate();
          }
        }
      ]
    });

    await alert.present();
  }

  async presentAlertActive() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onActive();
          }
        }
      ]
    });

    await alert.present();
  }

  async presentAlertDeActive() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onDeActive();
          }
        }
      ]
    });

    await alert.present();
  }

  async presentAlertVerifyEdit() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onVerifyEdit();
          }
        }
      ]
    });

    await alert.present();
  }

  onActive() {

    SharedIonic.loading(this.loadingController);

    this.productService.ActiveDesign(this.productDetail.productDesigns[this.selectedVideoIndex].id).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {

          this.productDetail.productDesigns[this.selectedVideoIndex].isActive = true;

          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onDeActive() {

    SharedIonic.loading(this.loadingController);

    this.productService.DeActiveDesign(this.productDetail.productDesigns[this.selectedVideoIndex].id).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {

          this.productDetail.productDesigns[this.selectedVideoIndex].isActive = false;

          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onVerifyEdit() {

    SharedIonic.loading(this.loadingController);

    this.productService.VerifyDesignEdit(this.productDetail.productDesigns[this.selectedVideoIndex].id).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {

          this.productDetail.productDesigns[this.selectedVideoIndex].isEdited = false;

          this.updateForm.setValue({
            title: this.updateForm2.value.title,
            description: this.updateForm2.value.description,
            price: this.updateForm2.value.price,
            offPrice: this.updateForm2.value.offPrice,
            count: this.updateForm2.value.count,
            weight: this.updateForm2.value.weight,
            isShow: this.updateForm2.value.isShow
          });
          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  async presentAlertConfirm3() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onAdd();
          }
        }
      ]
    });

    await alert.present();
  }

  onDelete(index: number | string): void {

    this.selectedVideoIndex = +index;

    SharedIonic.loading(this.loadingController);

    this.productService.AdminDeleteDesign(this.productDetail.productDesigns[this.selectedVideoIndex].id).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {

          this.productDetail.productDesigns.splice(this.selectedVideoIndex, 1);
          this.productDetail2.productDesigns.splice(this.productDetail2.productDesigns.findIndex(e => e.productDesignId == this.productDetail.productDesigns[this.selectedVideoIndex].id), 1);

          this.updateForm.setValue({
            title: '',
            description: '',
            price: '',
            offPrice: '',
            count: '',
            weight: '',
            isShow: true
          });
          this.updateForm2.setValue({
            title: '',
            description: '',
            price: '',
            offPrice: '',
            count: '',
            weight: '',
            isShow: true
          });
          // this.selectedCourseId = 0;
          // this.courseSelected = false;
          // this.setQueryParams(1);
          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onUpdate() {

    if (this.updateForm.valid || this.selectedVideoIndex != -1) {

      SharedIonic.loading(this.loadingController);

      this.productService.AdminAddOrUpdateDesign(
        new ProductDesignViewModel(
          this.productDetail.productDesigns[this.selectedVideoIndex].id,
          this.productDetail.id,
          this.updateForm.value.count,
          this.updateForm.value.price,
          this.updateForm.value.offPrice,
          this.productDetail.productDesigns[this.selectedVideoIndex].isActive,
          this.updateForm.value.isShow,
          this.updateForm.value.title,
          this.updateForm.value.description,
          true,
          this.updateForm.value.weight
        )
      ).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {

            this.productDetail.productDesigns[this.selectedVideoIndex].title = this.updateForm.value.title;
            this.productDetail.productDesigns[this.selectedVideoIndex].price = this.updateForm.value.price;
            this.productDetail.productDesigns[this.selectedVideoIndex].offPrice = this.updateForm.value.offPrice;
            this.productDetail.productDesigns[this.selectedVideoIndex].isShow = this.updateForm.value.isShow;
            this.productDetail.productDesigns[this.selectedVideoIndex].description = this.updateForm.value.description;
            this.productDetail.productDesigns[this.selectedVideoIndex].count = this.updateForm.value.count;
            this.productDetail.productDesigns[this.selectedVideoIndex].weight = this.updateForm.value.weight;

            this.updateForm.setValue({
              title: '',
              description: '',
              price: '',
              offPrice: '',
              count: '',
              weight: '',
              isShow: true
            });

            this.productDetail2.productDesigns[this.selectedVideoIndex].title = this.updateForm.value.title;
            this.productDetail2.productDesigns[this.selectedVideoIndex].price = this.updateForm.value.price;
            this.productDetail2.productDesigns[this.selectedVideoIndex].offPrice = this.updateForm.value.offPrice;
            this.productDetail2.productDesigns[this.selectedVideoIndex].isShow = this.updateForm.value.isShow;
            this.productDetail2.productDesigns[this.selectedVideoIndex].description = this.updateForm.value.description;
            this.productDetail2.productDesigns[this.selectedVideoIndex].count = this.updateForm.value.count;
            this.productDetail2.productDesigns[this.selectedVideoIndex].weight = this.updateForm.value.weight;

            this.updateForm2.setValue({
              title: '',
              description: '',
              price: '',
              offPrice: '',
              count: '',
              weight: '',
              isShow: true
            });
            this.selectedVideoIndex = -1;
            // this.onSelectItem(this.course);
            SharedIonic.successToast(this.toastController);
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

  onAdd() {

    if (this.addForm.valid) {

      SharedIonic.loading(this.loadingController);

      this.productService.AdminAddOrUpdateDesign(
        new ProductDesignViewModel(
          0,
          this.productDetail.id,
          this.addForm.value.count,
          this.addForm.value.price,
          this.addForm.value.offPrice,
          false,
          this.addForm.value.isShow,
          this.addForm.value.title,
          this.addForm.value.description,
          false,
          this.addForm.value.weight
        )
      ).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {
            this.addForm.setValue({
              title: '',
              description: '',
              price: '',
              offPrice: '',
              count: '',
              weight: '',
              isShow: true
            });
            this.onSelectItem(this.product);
            SharedIonic.successToast(this.toastController);
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

  MakePageCountArray(pageCount: number | string): Array<number | string> {

    const array: string[] = [];

    for (let i = 1; i <= pageCount; i++) {

      array.push(i.toString());
    }

    return array;
  }

  goPreviousPage() {

    if (this.filteredProducts.startPage == null) {
      return;
    }
    if (this.filteredProducts.pageId > this.filteredProducts.startPage && +this.filteredProducts.pageId - 1 > 0) {
      this.setQueryParams(+this.filteredProducts.pageId - 1);
    }
  }

  goNextPage() {

    if (this.filteredProducts.endPage == null) {
      return;
    }
    if (this.filteredProducts.pageId < this.filteredProducts.endPage) {
      this.setQueryParams(+this.filteredProducts.pageId + 1);
    }
  }

  goPage(pageId: number | string) {
    this.setQueryParams(+pageId);
  }

  setQueryParams(pageId: number) {

    this.filteredProducts.title = this.searchTitle;

    this.router
      .navigate(
        ['AdminPanel', 'ProductDesigns'],
        {
          queryParams:
          {
            page: pageId < 1 ? 1 : pageId,
            take: this.filteredProducts.takeEntity ? this.filteredProducts.takeEntity : null,
            title: this.filteredProducts.title ? this.filteredProducts.title : null,
            startPrice: this.filteredProducts.startPrice ? this.filteredProducts.startPrice : null,
            endPrice: this.filteredProducts.endPrice ? this.filteredProducts.endPrice : null,
            categoryIds: this.filteredProducts.categoryIds ? this.filteredProducts.categoryIds : [],
            sortId: this.filteredProducts.sortId ? this.filteredProducts.sortId : 0
          }
        });
  }

  onSelectItem(model: IProductModel) {

    this.selectedProductId = +model.id;
    this.selectedVideoIndex = -1;
    this.product = model;

    // tslint:disable-next-line: max-line-length
    this.productDetail = new ProductDetailModel(this.selectedProductId, model.name, model.price, model.offPrice, 0, model.shortDescription, model.description, '', false, false, model.createDate, model.lastUpdateDate, false, [], false, model.seller);
    this.productDetail2 = new ProductDetailModel(this.selectedProductId, model.name, model.price, model.offPrice, 0, model.shortDescription, model.description, '', false, false, model.createDate, model.lastUpdateDate, false, [], false, model.seller);

    SharedIonic.loading(this.loadingController);

    this.productService.GetAdminProductDetailDesignsById(this.selectedProductId).subscribe(
      res => {
        if (GResponse.SuccessStatus === res.status) {

          const design = [];

          res.data.forEach(v => {
            design.push(
              // tslint:disable-next-line: max-line-length
              new ProductDesignViewModel(v.id, v.productId, v.count, v.price, v.offPrice, v.isActive, v.isShow, v.title, v.description, v.isEdited, v.weight, v.productDesignId)
            );
          });

          this.productDetail.productDesigns = design;

          this.updateForm.setValue({
            title: '',
            description: '',
            price: '',
            offPrice: '',
            count: '',
            weight: '',
            isShow: true
          });

          this.productService.GetAdminProductDetailDesignsEditById(this.selectedProductId).subscribe(
            res => {
              SharedIonic.dismissLoading(this.loadingController);
              if (GResponse.SuccessStatus === res.status) {

                const design = [];

                res.data.forEach(v => {
                  design.push(
                    // tslint:disable-next-line: max-line-length
                    new ProductDesignViewModel(v.id, v.productId, v.count, v.price, v.offPrice, v.isActive, v.isShow, v.title, v.description, v.isEdited, v.weight, v.productDesignId)
                  );
                });

                this.productDetail2.productDesigns = design;

                this.updateForm2.setValue({
                  title: '',
                  description: '',
                  price: '',
                  offPrice: '',
                  count: '',
                  weight: '',
                  isShow: true
                });

                this.productSelected = true;
              } else {
                this.productDetail2.productDesigns = [];
                this.selectedProductId = this.productDetail.id;
                this.productSelected = true;
              }
            },
            err => {
              SharedIonic.dismissLoading(this.loadingController);
              this.productDetail.productDesigns = [];
              this.selectedProductId = 0;
              this.productSelected = false;
            }
          );
        } else {

          SharedIonic.dismissLoading(this.loadingController);
          this.productDetail.productDesigns = [];
          this.selectedProductId = this.productDetail.id;
          this.productSelected = true;
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        this.productDetail.productDesigns = [];
        this.selectedProductId = 0;
        this.productSelected = false;
      }
    );
  }

  onCancel() {

    this.selectedProductId = 0;
    this.productSelected = false;
  }
}
